pub(super) fn localized_catalog(locale: &str) -> Option<&'static [SearchRow]> {
    match locale {
        "de" => Some(SETTINGS_SEARCH_DE),
        "en-GB" => Some(SETTINGS_SEARCH_EN_GB),
        "es" => Some(SETTINGS_SEARCH_ES),
        "fr" => Some(SETTINGS_SEARCH_FR),
        "ja" => Some(SETTINGS_SEARCH_JA),
        "ko" => Some(SETTINGS_SEARCH_KO),
        "pt-BR" => Some(SETTINGS_SEARCH_PT_BR),
        "ru" => Some(SETTINGS_SEARCH_RU),
        "uk" => Some(SETTINGS_SEARCH_UK),
        "zh-CN" => Some(SETTINGS_SEARCH_ZH_CN),
        "zh-TW" => Some(SETTINGS_SEARCH_ZH_TW),
        _ => None,
    }
}
